import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel for depthwise 2D convolution (FP32)
# ----------------------------------------------------------------------
conv2d_kernel_source = """
__global__ void depthwise_conv_kernel(
    const float* __restrict__ x,
    const float* __restrict__ kernel,
    float* __restrict__ out,
    int B, int C, int H, int W, int KH, int kW, int stride, int pad_h, int pad_w, int out_h, int out_w
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * C * out_h * out_w) return;

    // Decode linear index to (b, c, oh, ow)
    int total_per_elem = C * out_h * out_w;
    int b = idx / (total_per_elem * out_w);
    int rem = idx % (total_per_elem * out_w);
    int c = rem / (out_h * out_w);
    rem %= (out_h * out_w);
    int oh = rem / out_w;
    int ow = rem % out_w;

    float sum = 0.0f;
    for (int kh = 0; kh < KH; ++kh) {
        for (int kw = 0; kw < kW; ++kw) {
            int ih = oh * stride + kh + pad_h;
            int iw = ow * stride + kw + pad_w;
            if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                int idx_in = ((b * C + c) * H + oh) * W + iw;
                sum += x[idx_in];
            }
        }
    }
    out[idx] = sum;
}
"""

# ----------------------------------------------------------------------
# C++ wrapper declaration
# ----------------------------------------------------------------------
conv2d_cpp_source = 'torch::Tensor depthwise_conv_cuda(torch::Tensor x, torch::Tensor kernel);'

# ----------------------------------------------------------------------
# Register the custom CUDA function via load_inline
# ----------------------------------------------------------------------
conv2d_load = load_inline(
    name="depthwise_conv",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_kernel_source,
    functions=["depthwise_conv_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Optimized model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias = bias

        # Keep the original conv2d for reference (optional)
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size, stride=stride, padding=padding, groups=in_channels, bias=bias)

        # Register the custom depthwise convolution operator
        self.depthwise_conv = load_inline(
            name="depthwise_conv",
            cpp_sources=conv2d_cpp_source,
            cuda_sources=conv2d_kernel_source,
            functions=["depthwise_conv_cuda"],
            verbose=True,
            extra_cflags=[],
            extra_ldflags=[]
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # The custom function expects (x, kernel)
        out = conv2d_load(x, self.conv2d.weight)
        return out
